actions.script:
const calls = ec.resource.script('component://mr-boss/screen/Commerce/Website/ThemeCalls.js')
const out = calls.probe('mantle.public.ThemeServices.get#ThemeComposition', {themeId})
if (!out.errors) {
    const bindings = calls.probe('mantle.public.ThemeServices.get#ThemeBindings', {themeId})
    const assets = calls.probe('mantle.public.ThemeServices.get#ThemeAssets', {themeId})
    const translations = calls.probe('mantle.public.ThemeServices.get#ThemeTranslations', {themeId, locale: locale || null})
    const sites = bindings.sites || []
    // the pages of the theme's first site, for TemplateAssignment (find#SitePages checks the site's store)
    const sitePages = sites.length ? calls.probe('mantle.public.ThemeServices.find#SitePages', {siteId: sites[0].siteId, pageSize: 100}) : {}
    Object.assign(out, {sites, sitePages: sitePages.pages || [],
        assets: assets.assets || [], translations, can: {edit: !!commerce.capabilities.themeEdit,
        code: !!commerce.capabilities.themeCode, publish: !!commerce.capabilities.themePublish},
        detailUrl: commerce.webBase + '/Website/ThemeDetail?themeId=' + encodeURIComponent(themeId),
        sourceUrl: commerce.webBase + '/Website/TemplateEditor?themeId=' + encodeURIComponent(themeId)})
}
ec.web.sendJsonResponse(out)

const calls = ec.resource.script('component://mr-boss/screen/Commerce/Website/ThemeCalls.js')
calls.send('store#ThemeSettings', {themeId, expectedRevision, template: template || null, sectionId: sectionId || null,
    blockId: blockId || null, settings: calls.json(settingsJson) || {}})

const calls = ec.resource.script('component://mr-boss/screen/Commerce/Website/ThemeCalls.js')
calls.send('store#ThemeAsset', {themeId, expectedRevision, path: assetPath,
    assetFile: (assetFile && Number(assetFile.size) > 0) ? assetFile : null})

const calls = ec.resource.script('component://mr-boss/screen/Commerce/Website/ThemeCalls.js')
calls.send('assign#ThemeTemplate', {themeId, targetKind: 'page', sitePageId, templateKey: templateKey || '',
    expectedRevision: publicationRevision === '' || publicationRevision == null ? null : publicationRevision})

const calls = ec.resource.script('component://mr-boss/screen/Commerce/Website/ThemeCalls.js')
const made = calls.probe('mantle.public.ThemeServices.create#ThemePreview', {themeId, siteId, pageKind: pageKind || 'home',
    targetId: targetId || null, locale: locale || null})
if (!made.errors) made.previewUrl = calls.previewUrl(made)
ec.web.sendJsonResponse(made)
